import {urbanSeries,forestData,brazilPaths,cityUKPath,urbanSourceUpdated} from './cities-data.js?v=20261024-cities01';
export {urbanSeries,forestData,urbanSourceUpdated};
export const citiesViews={
 'eco-forest-loss-gis':[['year23','2023 area'],['year24','2024 area'],['change','Relative change'],['join','How layers join']],
 'city-urban-trends':[['compare','Compare countries'],['uk','UK series'],['definitions','Compare definitions'],['measure','Count versus share']],
 'city-urban-causes':[['migration','Migration pathway'],['balance','Population balance'],['capacity','Housing capacity'],['components','Three contributions']],
 'city-uk-distribution':[['england','English centres'],['nations','Scotland,Wales,NI'],['share','England2021shares'],['boundaries','Which boundary?']],
 'city-uk-regional-change':[['industry','Industrial legacy'],['connections','Jobs & connections'],['mobility','Commuting & moving'],['measure','Degree versus change']]
};
export const citiesRequirements=Object.fromEntries(Object.entries(citiesViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const citiesAnimated=(k,v)=>k==='city-urban-causes'?['migration','balance','capacity'].includes(v):k==='city-uk-regional-change'?v!=='measure':false;
export const pctChange=(old,value)=>(value-old)/old*100;
export const urbanShare=(urban,total)=>urban/total*100;
export const populationBalance=(start,births,deaths,inward,outward)=>start+births-deaths+inward-outward;
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b6cbd4',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=5,c='#efb59f')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?66:45}" rx="12" fill="#35566a" stroke="#aac2cc"/>`+tx(x+12,y+26,a,12)+(b?tx(x+12,y+48,b,11):'');
const svg=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#edf2f1" font-family="sans-serif">${b}</g></svg>`;
const wrap=(b,c)=>svg(b,c)+`<p class="geo-caption">${c}</p>`;
const sourceLink=(url,label)=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`;
const forestSource=()=>`<p class="geo-caption">INPE PRODES2024 consolidated,July2025 · ${sourceLink('https://data.inpe.br/biomasbr/wp-content/uploads/sites/3/2025/07/Nota_tecnica_PRODES_2024_consolidada.pdf','tables1–2')} · ${sourceLink('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth boundaries,public domain')}. Four selected states only;annual indicator period2024:1Aug2023–31Jul2024. Not all forest loss or exact clearing locations.</p>`;
const urbanSource=()=>`<p class="geo-caption">${sourceLink('https://data.worldbank.org/indicator/SP.URB.TOTL.IN.ZS','World Bank / UNWUP')} · national urban definitions · API updated${urbanSourceUpdated} · ${sourceLink('https://creativecommons.org/licenses/by/4.0/','CC BY4.0')}.1975–2025annual series;definitions and revisions affect comparisons. Not the harmonised city-only measure.</p>`;
const forestLabels={'BR-AM':[145,137],'BR-PA':[310,137],'BR-MT':[288,235],'BR-RO':[184,215]};
export function forestMap(mode='year24',neutral=false){const rel=mode==='change',year=mode==='year23'?2023:2024;let b=tx(20,28,rel?'PRODES ·2023→2024 CHANGE':'PRODES ·'+year+' AREA',16)+tx(20,50,rel?'Relative annual change (%)':'Annual primary-forest clearance (km²)',12);
 for(const s of forestData){const value=rel?pctChange(s.old,s.new):year===2023?s.old:s.new,col=rel?'#8eb7ae':value>=2000?'#eab49d':value>=1000?'#a6c1b2':'#7699ad';b+=`<path d="${brazilPaths[s.code]}" fill="${col}" stroke="#e1e9e5" stroke-width="1.4"/>`;const[x,y]=forestLabels[s.code];b+=`<rect x="${x-47}" y="${y-19}" width="94" height="39" rx="6" fill="#183246e8"/>`+tx(x-40,y-3,s.name,11)+tx(x-40,y+13,rel?value.toFixed(1)+'%':String(value),12);}
 b+=tx(20,304,'Four selected states · others not displayed',12)+(rel?tx(20,325,'Negative = smaller annual area,not forest regrowth',11):tx(20,325,'Colours:under1000 /1000–1999 /2000+km²',11));
 return wrap(b,neutral?'Four-state regional data map. Read state labels,annual date andkm²values.':rel?'Each value is the percentage change in the annual PRODESindicator,using2023as denominator. It is not the percentage of a state cleared or a regrowth rate.':'Genuine Natural Earth state geometry joined to INPE annual regional attributes by ISOcode. Whole-state colour summarises the selected indicator;it does not locate actual clearings or show all state land was cleared. Some mapped territory lies outside the monitored region.')+forestSource();}
export function urbanChart(kind='compare',neutral=false){let ids=kind==='uk'?['GBR']:kind==='china'?['CHN']:['GBR','CHN','NGA'];const colours={GBR:'#edb59f',CHN:'#bad3c0',NGA:'#b0cee5'},y=v=>280-v*2.05,x=v=>55+(v-1975)*6.9;let b=tx(20,25,'URBAN POPULATION SHARE ·1975–2025',14)+tx(20,49,'% of national population ·0–100scale',12);
 for(let n=0;n<=100;n+=25)b+=path(`M55 ${y(n)}H405`,'#839dad55',1)+tx(20,y(n)+4,String(n),11);
 for(let s of urbanSeries.filter(s=>ids.includes(s.code)))b+=`<polyline points="${s.values.map(p=>`${x(p.year).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ')}" fill="none" stroke="${colours[s.code]}" stroke-width="3"/>`+dot(x(2025),y(s.values.at(-1).value),4,colours[s.code]);
 b+=tx(42,300,'1975',11)+tx(212,300,'2000',11)+tx(383,300,'2025',11)+tx(20,331,'UK',12)+path('M45 327H75',colours.GBR,4)+tx(100,331,'China',12)+path('M143 327H173',colours.CHN,4)+tx(200,331,'Nigeria',12)+path('M250 327H280',colours.NGA,4);
 const rows=urbanSeries.filter(s=>ids.includes(s.code));return wrap(b,neutral?'Annual urban-share series for the three labelled countries;matching percentage scale. Source definitions below.':'Each point is an archived annual World Bank/UNvalue;no invented interpolation or axis change. These examples show contrasts,not uniform histories for every developed,emerging or developing country.')+urbanSource()+`<details class="geo-chart-values"><summary>Read comparison values</summary><table class="geo-data"><caption>National urban share,rounded to1decimal%</caption><thead><tr><th scope="col">Country</th><th scope="col">1975</th><th scope="col">2000</th><th scope="col">2025</th></tr></thead><tbody>${rows.map(s=>`<tr><th scope="row">${s.name}</th>${[1975,2000,2025].map(y=>`<td>${s.values.find(p=>p.year===y).value.toFixed(1)}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;}
const cityPositions=[['Newcastle',-1.6178,54.9783,'england',90],['Leeds',-1.5491,53.8008,'england',126],['Manchester',-2.2426,53.4808,'england',162],['Liverpool',-2.98,53.4084,'england',198],['Birmingham',-1.9026,52.4862,'england',234],['London',-.1278,51.5074,'england',270],['Glasgow',-4.2518,55.8642,'nations',95],['Edinburgh',-3.1883,55.9533,'nations',135],['Belfast',-5.9301,54.5973,'nations',210],['Cardiff',-3.1791,51.4816,'nations',280]];
export function ukCityMap(which='england'){let b=tx(20,27,'UK URBAN CENTRES · LOCATE,NOT RANK',13)+`<path d="${cityUKPath}" fill="#849e96" stroke="#c4d3cf" stroke-width="1.4"/>`;
 for(const[name,lon,lat,group,ly]of cityPositions){const x=60+(lon+8.7)*20,y=315-(lat-49.8)*24;b+=dot(x,y,group===which?4:2,group===which?'#efb59f':'#c6d7dc');if(group===which)b+=path(`M${x+5} ${y}L295 ${ly-4}`,'#bed0d7',1)+tx(302,ly,name,12);}
 b+=path('M385 75V45m0 0-5 10m5-10 5 10','#d9e3e7',2)+tx(380,92,'N',12)+tx(20,340,'Generalised locator · dots are not urban boundaries',11);return wrap(b,'Natural Earth110mUKoutline,public domain;approximate city-centre positions for orientation. Selected major centres,not every settlement,a population-density map or a ranking of city populations. Generalised islands and coastlines.')+`<p class="geo-caption">${sourceLink('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth geometry')} · ${sourceLink('https://www.gov.uk/government/publications/toponymic-guidelines/toponymic-guidelines-for-map-and-other-editors-united-kingdom-of-great-britain-and-northern-ireland--2','UK place-name guidance')}</p>`;}
export function citiesScene(k,v,t=0){if(!citiesViews[k])return '';v=citiesRequirements[k].includes(v)?v:citiesRequirements[k][0];t=citiesAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='';
if(k==='eco-forest-loss-gis'){if(v!=='join')return forestMap(v);b=tx(20,28,'SPATIAL FEATURES + ATTRIBUTE TABLE',14)+box(25,80,180,'Boundary geometry','BR-PA / Pará')+box(235,80,180,'INPE attribute row','BR-PA /2024:2395')+path('M115 150L210 215M325 150L230 215')+box(95,225,250,'Join on the same code','One region,its annual value')+tx(20,330,'Source layers retain dates,units and definitions',12);c='A shared state identifier joins a genuine polygon feature to an indicator row. A regional join is GISanalysis support;it is not proof of exact clearing locations or practice in every GISsoftware operation.';return wrap(b,c)+forestSource();}
if(k==='city-urban-trends'){
 if(v==='definitions')return wrap(tx(20,28,'SAME LABEL?CHECK THE DEFINITION',14)+box(25,80,390,'National urban classifications','Country criteria can differ')+box(25,200,390,'Harmonised cities / towns / rural','City-only share excludes some urban-type areas'),'Different settlement definitions measure different populations. Do not treat the national urban-share series as the UN2025city-only share or infer a global reversal by switching definitions.');if(v!=='measure')return urbanChart(v);b=tx(20,28,'URBAN COUNT ≠ URBAN SHARE',15)+box(25,80,180,'Before:50of100','Urban share50%')+box(235,80,180,'After:60of150','Urban share40%')+path('M125 175H315')+tx(75,230,'Urban residents:+10',16)+tx(75,275,'Urban share:−10percentage points',14)+tx(20,330,'Invented population example · check the denominator',11);c='Urban residents increase while their share falls because total population grows faster. The numbers are invented to isolate the denominator;they are not the World Bankcountry data.';
}
if(k==='city-urban-causes'){
 if(v==='migration'){b=tx(20,28,'WORK,SERVICES AND MIGRATION',14)+box(25,85,170,'Rural origins','Varied pressures')+box(245,85,170,'Urban destinations','Jobs / education / services')+path('M110 185Q220 260 330 185')+dot(110+220*t,185+70*Math.sin(Math.PI*t),7)+tx(20,315,'Choices and constraints vary;outcomes are unequal',11);c='A symbolic movement links rural pressures with urban opportunities. Rural-to-urban migration is one pathway,not the only contribution to urban growth;not every mover obtains the same benefits.';}
 else if(v==='balance'){const n=100+12*t;b=tx(20,28,'URBAN POPULATION · INVENTED BALANCE',13)+box(120,140,200,`Residents:${n.toFixed(0)}`,'Start100 → end112')+box(20,60,180,'Births12 − deaths4','Natural increase:+8')+box(240,60,180,'In6 − out2','Net migration:+4')+path('M115 128L160 135M325 128L280 135')+dot(115+45*t,128+7*t)+dot(325-45*t,128+7*t)+tx(20,325,'No reclassification in this example;not national share',11);c='The toy balance adds8through natural increase and4through net migration. Dots and timing are symbolic;this is not a named city or evidence that its national urban share rises.';}
 else if(v==='capacity'){const demand=100+20*t,supply=100+10*t;b=tx(20,28,'HOUSEHOLDS AND HOUSING PLACES',14)+`<rect x="45" y="105" width="${demand*2.5}" height="50" rx="8" fill="#e8b59f"/><rect x="45" y="215" width="${supply*2.5}" height="50" rx="8" fill="#a8c9bf"/>`+tx(55,136,`Demand:${demand.toFixed(0)} households`,13)+tx(55,246,`Places:${supply.toFixed(0)}`,13)+tx(20,325,`Toy shortfall:${(demand-supply).toFixed(0)} places · supply/access matter`,12);c='Invented demand grows from100to120households while housing places grow from100to110. A10place shortfall results. Affordability,quality and allocation also matter;the animation is not observed informal-settlement growth.';}
 else{b=tx(20,28,'THREE CONTRIBUTIONS TO URBAN NUMBERS',13)+box(35,65,370,'Natural change','Births minus deaths')+box(35,155,370,'Net migration','Arrivals minus departures')+box(35,245,370,'Reclassification','Changes in status or boundaries');c='Recorded urban population can change through demography,migration and classification. These contributions must be separated;an increase in the number urban is not automatically an increase in national urban share.';}
}
if(k==='city-uk-distribution'){
 if(v==='england'||v==='nations')return ukCityMap(v);
 if(v==='share'){b=tx(20,28,'ENGLAND2021 · POPULATION SHARE',14)+tx(20,65,'Defra /2021RuralUrbanClassification',12)+`<rect x="40" y="140" width="${360*.831}" height="65" fill="#a9c9c1"/><rect x="${40+360*.831}" y="140" width="${360*.169}" height="65" fill="#e9b7a1"/>`+tx(50,240,'Urban83.1%',16)+tx(265,240,'Rural16.9%',16)+tx(20,305,'England figures,not a whole-UKestimate',13)+tx(20,330,'Population share,not percentage of land covered',12);c='The2021classification gives England urban83.1%and rural16.9%. These refer to people under that definition,not the whole UKor the fraction of land built up.';return wrap(b,c)+`<p class="geo-caption">${sourceLink('https://assets.publishing.service.gov.uk/media/67d875029dc953ac3bfe937b/1_Population_18_03_2025.pdf','Defra March2025digest,tableA-1')} · ${sourceLink('https://www.ons.gov.uk/methodology/geography/geographicalproducts/ruralurbanclassifications/2021ruralurbanclassification','ONS classification')}</p>`;}
 b=tx(20,28,'SAME PLACE,DIFFERENT STATISTICAL BOUNDARIES',12)+`<ellipse cx="220" cy="180" rx="165" ry="105" fill="#668b9750" stroke="#b9cfd4"/><circle cx="220" cy="180" r="55" fill="#a6bda6" stroke="#d4dfd6"/>`+tx(181,184,'City area',13)+tx(95,280,'Wider conurbation / commuting links',12)+tx(20,330,'Schematic only;boundaries vary by definition',12);c='Administrative cities,built-up areas and wider functional areas can include different residents. This conceptual nested-boundary diagram is not a real city boundary map or a comparative population dataset.';
}
if(k==='city-uk-regional-change'){
 if(v==='measure'){b=tx(20,28,'LEVEL AND CHANGE · INVENTED REGIONS',13)+box(25,85,180,'A:80% →82%','Change:+2points')+box(235,85,180,'B:40% →50%','Change:+10points')+tx(25,235,'A:higher final degree',15)+tx(25,275,'B:larger rise over the same period',14)+tx(20,330,'Use consistent boundaries,definitions and dates',12);c='Ahas the higher urban share but the smaller percentage-point increase. These numbers are invented,not regional ONSestimates. A real trend comparison needs consistent classification and time period.';}
 else if(v==='industry'){b=tx(20,28,'INDUSTRIAL LEGACY AND LATER CHANGE',13)+box(25,75,180,'Coal / ports / rail','Earlier urban jobs')+box(235,75,180,'Industry / housing','Concentrated settlement')+path('M110 155Q220 230 330 155')+dot(110+220*t,155+70*Math.sin(Math.PI*t),7)+tx(20,285,'Later restructuring has varied local outcomes',13)+tx(20,330,'History helps explain pattern,not one fixed future',12);c='Employment,transport and housing contributed to industrial urban concentrations at different times. Deindustrialisation and later services or regeneration vary across cities;industrial history does not imply all northern places follow the same decline.';}
 else if(v==='connections'){b=tx(20,28,'JOBS,SERVICES AND CONNECTIONS',14)+box(25,75,180,'Firms / universities','Investment and skills')+box(235,75,180,'People / services','Access and opportunity')+path('M100 170H340M100 240H340')+dot(100+240*t,170)+dot(340-240*t,240)+tx(20,305,'Transport,housing and planning mediate change',12);c='Links between people,employment and services can reinforce urban concentrations. Movement is symbolic,not measured migration flows or proof that a better-connected place always grows fastest.';}
 else{b=tx(20,28,'COMMUTING IS NOT ALWAYS MIGRATION',14)+box(25,85,175,'Home outside centre')+box(240,85,175,'Urban workplace')+path('M100 180H340')+dot(100+240*(t<.5?t*2:2-t*2),180,7)+tx(20,260,'Daily travel:usual residence can stay the same',12)+tx(20,310,'Suburbanisation / counter-urbanisation involve',12)+tx(20,330,'residential change;check which process is shown',12);c='The moving commuter travels between home and work without a permanent residential move. Transport can also support suburbanisation or moves to smaller settlements,but a daily journey alone does not establish migration or a change in urban classification.';}
}
return wrap(b,c);}
